import json, re
from collections import defaultdict

fpath = "/home/ubuntu/.claude-account-2/projects/-home-ubuntu--agent-ml-research-idea-gen-0509-3-projects-solver-trace-ablation--claude-sessions-reviewer-5c7e23f1/af5f26bd-940d-4b3a-8759-6e3a19b692d1/tool-results/mcp-agent-ml-research-read_registry-1779330159486.txt"

with open(fpath, 'r') as f:
    raw = json.load(f)

data = json.loads(raw['result'])
experiments = data['data']['experiments']

# Classification function
def classify(eid, exp):
    hyp = (exp.get('hypothesis', '') or '').lower()
    notes = (exp.get('notes', '') or '').lower()
    metrics = exp.get('metrics', {}) or {}
    full = f"{eid} {hyp} {notes}".lower()
    eval_data = (metrics.get('eval_data', '') or '').lower() if isinstance(metrics, dict) else ''

    info = {
        'id': eid,
        'reward': None,
        'dataset': None,
        'logic': None,
        'seed': None,
        'steps': None,
        'model': None,
    }

    # === REWARD CONDITION ===
    eid_l = eid.lower()

    if 'shuffled-isr' in eid_l or 'shuffled-isr' in full:
        info['reward'] = 'Shuffled-ISR β=0.1'
    elif 'sft' in eid_l or 'sft' in full:
        info['reward'] = 'SFT'
    elif 'gated-isr' in eid_l or 'gated-isr' in full:
        info['reward'] = 'Gated-ISR'
    elif 'random' in eid_l or 'random' in full:
        # Determine beta
        if 'b03' in eid_l or 'β=0.3' in full or 'b=0.3' in full or 'b03' in full:
            info['reward'] = 'Random β=0.3'
        elif 'b005' in eid_l or 'β=0.05' in full or 'b005' in full:
            info['reward'] = 'Random β=0.05'
        elif 'b01' in eid_l or 'β=0.1' in full or 'b01' in full:
            info['reward'] = 'Random β=0.1'
        elif 'b02' in eid_l or 'β=0.2' in full:
            info['reward'] = 'Random β=0.2'
        else:
            info['reward'] = 'Random (unknown β)'
    elif 'isr' in eid_l or 'isr' in full:
        if 'b03' in eid_l or 'β=0.3' in full or 'b=0.3' in full or 'b03' in full:
            info['reward'] = 'ISR β=0.3'
        elif 'b02' in eid_l or 'β=0.2' in full or 'b02' in full:
            info['reward'] = 'ISR β=0.2'
        elif 'b01' in eid_l or 'β=0.1' in full or 'b01' in full:
            info['reward'] = 'ISR β=0.1'
        else:
            info['reward'] = 'ISR (unknown β)'
    elif 'exec' in eid_l or 'exec-only' in full or 'execution-only' in full:
        info['reward'] = 'Exec-only'
    elif 'gt-isr' in eid_l:
        info['reward'] = 'GT-ISR baseline'
    elif 'phase0' in eid_l or 'baseline' in eid_l:
        info['reward'] = 'Phase0-baseline'
    elif 'taxonomy' in eid_l or 'hacking-taxonomy' in full:
        info['reward'] = 'Taxonomy (meta)'
    elif '100step' in eid_l:
        info['reward'] = 'Exec-only (100-step)'
    else:
        info['reward'] = 'UNKNOWN'

    # === DATASET ===
    if 'prooffol' in full or 'proof_fol' in full or 'pf-' in eid_l or 'prooffol' in eval_data:
        info['dataset'] = 'ProofFOL'
    elif 'folio' in full or 'folio' in eval_data:
        info['dataset'] = 'FOLIO'
    elif 'proofwriter' in full or 'proofwriter' in eval_data:
        info['dataset'] = 'ProofWriter-FOL'
    else:
        info['dataset'] = 'ProofWriter-FOL'  # default assumption for most experiments

    # === LOGIC TYPE ===
    if 'prolog' in full or 'swi' in full or 'pf-' in eid_l or 'prooffol' in full:
        info['logic'] = 'Prolog'
    else:
        info['logic'] = 'FOL (Prover9)'

    # === SEED ===
    seed_match = re.search(r's(\d{2,3})', eid_l)
    if seed_match:
        info['seed'] = int(seed_match.group(1))
    else:
        # Try from hypothesis
        seed_match2 = re.search(r'seed[= ]*(\d{2,3})', full)
        if seed_match2:
            info['seed'] = int(seed_match2.group(1))

    # === TRAINING STEPS ===
    if '1000' in eid_l or '1000-step' in full or '1000 steps' in full or '-1000' in eid_l:
        info['steps'] = 1000
    elif '100step' in eid_l or '100-step' in full:
        info['steps'] = 100
    else:
        info['steps'] = 500  # default

    # === MODEL ===
    if '1.7b' in eid_l or '1_7b' in eid_l or '1.7b' in full or 'qwen3-1.7b' in full:
        info['model'] = 'Qwen3-1.7B'
    elif 'llama' in full or 'llama' in eid_l:
        info['model'] = 'LLaMA-3.2-3B'
    elif '4b' in eid_l or 'qwen3-4b' in full:
        info['model'] = 'Qwen3-4B'
    else:
        info['model'] = 'Qwen3-4B'  # default model for this project

    return info

# Classify all experiments
classified = []
for eid, exp in experiments.items():
    info = classify(eid, exp)
    classified.append(info)

# Print classification for review
print("=" * 120)
print(f"{'ID':<40} {'Reward':<22} {'Dataset':<18} {'Logic':<15} {'Seed':<6} {'Steps':<6} {'Model':<15}")
print("=" * 120)
for c in sorted(classified, key=lambda x: (x['reward'], x['dataset'], x['seed'] or 0)):
    print(f"{c['id']:<40} {c['reward']:<22} {c['dataset']:<18} {c['logic']:<15} {str(c['seed']):<6} {str(c['steps']):<6} {c['model']:<15}")

print(f"\nTotal: {len(classified)}")
